recent_command_receipts.command:
set -euo pipefail
cat > /tmp/find_secret.c <<'EOF'
#include <stdio.h>
#include <stdint.h>
#include <string.h>

static uint32_t crc32(const unsigned char *buf, size_t len) {
    uint32_t c = 0xFFFFFFFFu;
    for (size_t i = 0; i < len; i++) {
        c ^= buf[i];
        for (int k = 0; k < 8; k++) {
            c = (c & 1u) ? (c >> 1) ^ 0xEDB88320u : (c >> 1);
        }
    }
    return ~c;
}

int main(int argc, char **argv) {
    const uint32_t target = 0x62D5D25Fu;
    char line[256];
    for (int a = 1; a < argc; a++) {
        FILE *f = fopen(argv[a], "r");
        if (!f) continue;
        while (fgets(line, sizeof(line), f)) {
            size_t n = strcspn(line, "\r\n");
            line[n] = '\0';
            if (n != 9) continue;
            if (crc32((const unsigned char *)line, n) == target) {
                printf("FOUND:%s\n", line);
                fclose(f);
                return 0;
            }
        }
        fclose(f);
    }
    return 1;
}
EOF
gcc -O2 -o /tmp/find_secret /tmp/find_secret.c
pw=$(/tmp/find_secret /app/john/run/password.lst /app/john/run/bip-0039/english.txt /usr/share/dict/words /usr/share/dict/web2 2>/dev/null | sed -n 's/^FOUND://p' | head -n1)
if [ -z "$pw" ]; then
  echo "NO_MATCH_FOUND" >&2
  exit 1
fi
7z t -p"$pw" -y /app/secrets.7z >/tmp/7ztest.out 2>/tmp/7ztest.err
7z x -so -p"$pw" -y /app/secrets.7z secrets/secret_file.txt > /app/solution.txt
printf 'PASSWORD:%s\n' "$pw"
printf 'CONTENT:'
cat /app/solution.txt
printf '\n'
